def psi(expected, actual, epsilon=1e-6):
    if len(expected) != len(actual):
        raise ValueError("length mismatch")
    total = 0.0
    for e, a in zip(expected, actual):
        e = max(e, epsilon)
        a = max(a, epsilon)
        total += (a - e) * math.log(a / e)
    return total

