def weighted_log_loss(labels, probabilities, positive_weight):
    if len(labels) != len(probabilities) or not labels:
        raise ValueError("invalid input")
    total = 0.0
    for y, p in zip(labels, probabilities):
        p = min(1 - 1e-15, max(1e-15, p))
        total += -positive_weight * math.log(p) if y == 1 else -math.log(1 - p)
