        c, n = totals.get(r["slice"], (0,0))
        totals[r["slice"]] = (c + r["correct"], n + r["count"])
    valid = {s:c/n for s,(c,n) in totals.items() if n > 0}
    if not valid:
        raise ValueError("no data")
    return min(valid, key=lambda s: (valid[s], s))

def early_stopping(val_losses, patience, min_delta):
    best = float('inf')
    best_epoch = 0
    counter = 0
    for i, loss in enumerate(val_losses):
        if loss < best - min_delta:
            best = loss
            best_epoch = i
            counter = 0
        else:
            counter += 1
            if counter >= patience:
                return [i, best_epoch]
    return [len(val_losses) - 1, best_epoch]

def error_slice_metrics(records, slice_key):
    from collections import defaultdict
    groups = defaultdict(list)
    for r in records:
        groups[r[slice_key]].append(r)
    out = {}
    for key, rs in groups.items():
        correct = sum(1 for r in rs if r['y_true'] == r['y_pred'])
        out[key] = round(correct / len(rs), 6)
    return out

def top_k_filter(logits, k):
    if k <= 0:
        return []
    order = sorted(range(len(logits)), key=lambda i: (-logits[i], i))
    return order[:k]

def normalize_tokens(text):
    out = []
    for token in text.lower().split():
        token = token.strip(".,!?;:")
