    return rank*in_features + out_features*rank

def choose_model(request,models):
    eligible=[m for m in models if m["quality"]>=request["min_quality"] and (not request.get("sensitive") or m["local"])]
    if not eligible:
        raise ValueError("no model")
    return min(eligible,key=lambda m:(m["cost"],-m["quality"],m["name"]))["name"]

def quantize_symmetric(values,max_int):
    if max_int<=0:
        raise ValueError("invalid")
    peak=max((abs(v) for v in values),default=0)
    if peak==0:
        return {"values":[0 for _ in values],"scale":1.0}
    scale=peak/max_int
    return {"values":[round(v/scale) for v in values],"scale":scale}

def merge_adapters(base,deltas,weights):
    if len(deltas)!=len(weights) or any(len(d)!=len(base) for d in deltas):
        raise ValueError("dimension mismatch")
    return [base[j]+sum(w*d[j] for w,d in zip(weights,deltas)) for j in range(len(base))]

def validate_payload(payload):
    errors = []
    if not isinstance(payload, dict):
        return ["payload must be an object"]
    if not isinstance(payload.get("request_id"), str) or not payload.get("request_id"):
        errors.append("invalid request_id")
    features = payload.get("features")
    if not isinstance(features, list) or not features:
        errors.append("invalid features")
    elif any(not isinstance(x,(int,float)) or isinstance(x,bool) for x in features):
        errors.append("invalid feature value")
