def route_match(routes, path):
    path_parts = [p for p in path.split("/") if p != ""]
    for pattern, handler in routes:
        pat_parts = [p for p in pattern.split("/") if p != ""]
        if len(pat_parts) != len(path_parts):
            continue
        params = {}
        ok = True
        for pp, ap in zip(pat_parts, path_parts):
            if pp.startswith(":"):
                params[pp[1:]] = ap
            elif pp != ap:
                ok = False
                break
        if ok:
            return [handler, params]
    return None

def paginate(items, page, page_size):
    total = len(items)
    if page_size <= 0:
        total_pages = 0
    else:
        total_pages = (total + page_size - 1) // page_size
    if page < 1 or page_size <= 0:
        page_items = []
    else:
        start = (page - 1) * page_size
        page_items = items[start:start + page_size]
    return {
        "items": page_items,
        "page": page,
        "total_pages": total_pages,
        "has_next": page < total_pages,
        "has_prev": page > 1,
    }

def parse_query_params(qs):
    out = {}
    if not qs:
        return out
    for pair in qs.split("&"):
        if pair == "":
            continue
        if "=" in pair:
            k, v = pair.split("=", 1)
        else:
            k, v = pair, ""
        out.setdefault(k, []).append(v)
    return out

def admit_requests(queue_size, capacity, incoming):
    available = max(0, capacity - queue_size)
    accepted = min(incoming, available)
    return {"accepted":accepted,"rejected":incoming-accepted}

def rate_limiter(timestamps, limit, window):
    allowed_times = []
    result = []
    for t in timestamps:
        allowed_times = [x for x in allowed_times if x > t - window]
        if len(allowed_times) < limit:
            result.append(True)
            allowed_times.append(t)
        else:
            result.append(False)
    return result

def changed_artifacts(old, new):
    names = set(old) | set(new)
    return sorted(name for name in names if old.get(name) != new.get(name))

import hashlib

def cache_key(files):
    h = hashlib.sha256()
    for path in sorted(files):
        h.update(path.encode()); h.update(b"\0")
        h.update(files[path].encode()); h.update(b"\0")
    return h.hexdigest()

def missing_lineage(metadata):
