def bundle_fingerprint(model_hash,preprocessing_hash,schema_hash,image_digest):
    return hashlib.sha256("\n".join([model_hash,preprocessing_hash,schema_hash,image_digest]).encode()).hexdigest()

def backward_compatible(old, new):
    errors = []
    for name, spec in old.items():
        if name not in new:
            errors.append(f"removed:{name}")
        elif new[name]["type"] != spec["type"]:
            errors.append(f"type:{name}")
    for name, spec in new.items():
        if name not in old and spec.get("required",False):
            errors.append(f"new_required:{name}")
    return sorted(errors)

def trace_duration(spans):
    if not spans:
        return 0
    if any(s["end"]<s["start"] for s in spans):
        raise ValueError("invalid span")
    return max(s["end"] for s in spans)-min(s["start"] for s in spans)

def mean_shift_alert(reference_mean, current_mean, reference_std, threshold):
    if reference_std == 0:
        return current_mean != reference_mean
    return abs(current_mean-reference_mean) > threshold * reference_std

def accuracy_by_version(rows):
    totals = {}
    for r in rows:
        correct, count = totals.get(r["version"], (0,0))
        totals[r["version"]] = (correct + int(bool(r["correct"])), count + 1)
    return {v:c/n if n else 0.0 for v,(c,n) in totals.items()}

def collapsed_outputs(values, epsilon):
    if not values or epsilon < 0:
        raise ValueError("invalid input")
    mean = sum(values) / len(values)
    variance = sum((x-mean)**2 for x in values) / len(values)
    return variance <= epsilon

def sustained_breach(values, threshold, windows):
    if windows <= 0:
        raise ValueError("invalid windows")
    run = 0
    for i, value in enumerate(values):
        run = run + 1 if value > threshold else 0
        if run >= windows:
            return i - windows + 1
    return -1
